// Разбираем поле options (JSON-строка из multipart) и проверяем общий секрет.
const item = $input.first();
const body = item.json.body ?? item.json;
const headers = item.json.headers ?? {};

const expected = $env.N8N_WEBHOOK_TOKEN || '';
if (expected && headers['x-transcriber-token'] !== expected) {
  throw new Error('Неверный X-Transcriber-Token');
}

let options = {};
try {
  options = typeof body.options === 'string' ? JSON.parse(body.options) : (body.options || {});
} catch (e) {
  throw new Error('options не является корректным JSON: ' + e.message);
}

// Имя бинарного поля из multipart: webhook кладёт его под ключом поля формы.
const binaryKeys = Object.keys(item.binary || {});
const fileKey = binaryKeys.includes('file') ? 'file' : binaryKeys[0];
if (!fileKey) throw new Error('В запросе нет файла');

return [{
  json: {
    job_id: body.job_id || $execution.id,
    file_key: fileKey,
    filename: item.binary[fileKey].fileName || 'audio.wav',
    options: {
      language: options.language ?? null,
      model: options.model || $env.WHISPER__MODEL || 'Systran/faster-whisper-small',
      prompt: options.prompt ?? null,
      timestamps: options.timestamps === true,
      post_action: options.post_action || 'none',
      post_instruction: options.post_instruction ?? null,
      target_language: options.target_language || 'English',
      destinations: options.destinations || [],
      telegram_chat_id: options.telegram_chat_id || $env.TELEGRAM_CHAT_ID || '',
      webhook_url: options.webhook_url || $env.OUTBOUND_WEBHOOK_URL || '',
      meta: options.meta || {}
    }
  },
  binary: item.binary
}];

// Склеиваем ответ ASR с исходными параметрами задачи.
const asr = $input.first().json;
const src = $('Разбор параметров').first().json;

return [{
  json: {
    job_id: src.job_id,
    filename: src.filename,
    options: src.options,
    text: (asr.text || '').trim(),
    language: asr.language || src.options.language,
    duration: asr.duration ?? null,
    segments: (asr.segments || []).map(s => ({
      start: s.start, end: s.end, text: (s.text || '').trim(), speaker: s.speaker ?? null
    }))
  }
}];

// Собираем промпт под выбранное действие постобработки.
const d = $input.first().json;
const o = d.options;

const SYSTEM = 'Ты — редактор расшифровок. Работаешь строго с предоставленным текстом, ' +
  'не выдумываешь фактов. Отвечай на языке исходного текста, если не указано иное.';

const T = {
  summary: `Сделай краткое содержание расшифровки. Формат: 3–7 предложений связного текста, затем список ключевых тезисов. Сохрани имена, числа и термины.\n\nРАСШИФРОВКА:\n${d.text}`,
  minutes: `Составь протокол встречи: ## Участники ## Обсуждённые вопросы ## Принятые решения ## Задачи (что / кто / срок) ## Открытые вопросы. Если раздел не подтверждается текстом — «не зафиксировано».\n\nРАСШИФРОВКА:\n${d.text}`,
  bullets: `Преобразуй расшифровку в структурированный конспект: вложенные списки, заголовки по смысловым блокам, без повторов.\n\nРАСШИФРОВКА:\n${d.text}`,
  translate: `Переведи расшифровку на язык: ${o.target_language}. Сохрани абзацы и терминологию. Верни только перевод.\n\nРАСШИФРОВКА:\n${d.text}`,
  custom: `${o.post_instruction || 'Кратко перескажи текст.'}\n\nРАСШИФРОВКА:\n${d.text}`
};

return [{ json: { ...d, system_prompt: SYSTEM, user_prompt: T[o.post_action] || T.summary } }];

// Итоговый объект: работает и с веткой постобработки, и без неё.
const base = $('Сборка расшифровки').first().json;
let post_output = null;

const incoming = $input.first().json;
if (incoming && incoming.choices && incoming.choices.length) {
  post_output = (incoming.choices[0].message.content || '').trim();
}

return [{ json: { ...base, post_output, delivery_text: post_output || base.text } }];
